import React, { useState } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import logo from "../img/logotipo-educaweb.webp";
import { useNavigate } from "react-router-dom";
import { Dropdown } from "react-bootstrap";

const Navbar = () => {
  const navigate = useNavigate();
  const [showDropdown, setShowDropdown] = useState(false);

  // Verifica se o usuário está logado
  const isAuthenticated = localStorage.getItem("token") !== null;
  const user = isAuthenticated
    ? JSON.parse(localStorage.getItem("user"))
    : null;
  const firstLetter = user?.nome?.[0]?.toUpperCase() || "";

  const handleLogoClick = () => {
    navigate("/");
  };

  const handleLogout = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("user");
    navigate("/login");
  };

  const handleMinhaAreaClick = () => {
    if (!user) return;

    switch (user.tipo) {
      case "Aluno":
        navigate(`/listacurso/${user.alunoId}`);
        break;
      case "Professor":
        navigate(`/lecionalista/${user.professorId}`);
        break;
      case "Administrador":
        navigate("/admlistcurso");
        break;
      default:
        navigate("/");
    }
  };

  return (
    <nav className="navbar navbar-light bg-light d-flex justify-content-between px-3">
      <div
        className="d-flex align-items-center"
        style={{ cursor: "pointer" }}
        onClick={handleLogoClick}
      >
        <img
          src={logo}
          alt="EducaWeb"
          width="30"
          height="30"
          className="d-inline-block align-top me-2"
        />
        <span className="navbar-brand mb-0 h1">EducaWeb</span>
      </div>

      {isAuthenticated && (
        <Dropdown show={showDropdown} onToggle={setShowDropdown}>
          <Dropdown.Toggle
            variant="light"
            id="dropdown-user"
            className="rounded-circle p-0 border-0"
            style={{
              width: "35px",
              height: "35px",
              backgroundColor: "#6c757d",
              color: "white",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              cursor: "pointer",
            }}
          >
            {firstLetter}
          </Dropdown.Toggle>

          <Dropdown.Menu align="end">
            <Dropdown.Item disabled>Olá, {user?.nome}</Dropdown.Item>
            <Dropdown.Divider />
            <Dropdown.Item onClick={handleMinhaAreaClick}>
              Minha Área
            </Dropdown.Item>
            <Dropdown.Item onClick={handleLogout}>Logout</Dropdown.Item>
          </Dropdown.Menu>
        </Dropdown>
      )}
    </nav>
  );
};

export default Navbar;
